from itertools import combinations, product
import heapq


def _jobs(data, capacity, tie):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    if mandatory & blocked or len(mandatory) > k:
        return {"error": "impossible"}
    options = [j for j in jobs if j["id"] not in blocked]
    best_value = None
    best_ids = None
    for subset in combinations(options, k):
        ids = tuple(sorted(j["id"] for j in subset))
        if not mandatory.issubset(ids):
            continue
        counts = Counter(j["group"] for j in subset)
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in quotas.items()):
            continue
        active = []
        valid = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"])):
            active = [end for end in active if end > job["start"]]
            if len(active) >= capacity:
                valid = False
                break
            active.append(job["end"])
        if not valid:
            continue
        value = sum(j["value"] for j in subset)
        if (best_value is None or value > best_value or
                (value == best_value and
                 (ids < best_ids if tie == "smallest" else ids > best_ids))):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d=10000):
        return (n + d // 2) // d if mode == "half_up" else n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}
    domains = []
    for name in names:
        versions = [v for v in rows[name]
                    if v not in blocked.get(name, []) and
                    (name not in pins or v == pins[name])]
        domains.append(sorted(versions, reverse=True) + [-1])

    def feasible(chosen):
        installed = {name for name, version in zip(names, chosen) if version != -1}
        for name, bounds in roots.items():
            version = chosen[names.index(name)]
            if version == -1 or not bounds[0] <= version <= bounds[1]:
                return False
        reached, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in reached:
                return True
            version = chosen[names.index(name)]
            if version == -1:
                return False
            active.add(name)
            reached.add(name)
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                ov = chosen[names.index(other)]
                if ov == -1 or not dep["min"] <= ov <= dep["max"]:
                    return False
                if not visit(other):
                    return False
            active.remove(name)
            return True

        for name in roots:
            if not visit(name):
                return False
        return reached == installed

    for choice in product(*domains):
        if feasible(choice):
            return {"versions": {name: version for name, version in zip(names, choice)
                                 if version != -1}}
    return {"error": "unsatisfiable"}


def _routes(data):
    required = data.get("required", [])
    bits = {node: 0 for node in range(data["n"])}
    for i, node in enumerate(required):
        bits[node] |= 1 << i
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source, start = data["source"], data["start"]
    initial = (source, bits[source], data["coupons"])
    dist = {initial: start}
    queue = [(start, *initial)]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                choices.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_state = (next_node, mask | bits[next_node], next_remaining)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


